// ════════════════════════════════════════════════════════════
//  ROUTE NAMES
// ════════════════════════════════════════════════════════════
class AppRoutes {
  static const splash           = '/splash';
  static const login            = '/login';
  static const register         = '/register';
  static const forgotPassword   = '/forgot-password';
  static const termsConditions  = '/terms-conditions';
  static const dashboard        = '/dashboard';
  static const invoices         = '/invoices';
  static const invoiceCreate    = '/invoice-create';
  static const invoiceEdit      = '/invoice-edit';
  static const invoiceDetail    = '/invoice-detail';
  static const expenses         = '/expenses';
  static const expenseAdd       = '/expense-add';
  static const profile          = '/profile';
  static const settings         = '/settings';
}

// ════════════════════════════════════════════════════════════
//  AUTH MIDDLEWARE — protects dashboard & inner routes
// ════════════════════════════════════════════════════════════
class AuthMiddleware extends GetMiddleware {
  @override
  int? get priority => 1;

  @override
  RouteSettings? redirect(String? route) {
    final user = FirebaseAuth.instance.currentUser;

    // Not logged in → go to login
    if (user == null) {
      return const RouteSettings(name: AppRoutes.login);
    }
    return null; // allow
  }
}

// ────────────────────────────────────────────────────────────
//  TERMS MIDDLEWARE — checks if terms have been accepted
// ────────────────────────────────────────────────────────────
class TermsMiddleware extends GetMiddleware {
  @override
  int? get priority => 2;

  @override
  RouteSettings? redirect(String? route) {
    // SharedPreferences sync check (fast path)
    // Full async check happens in SplashScreen
    return null;
  }
}

// ════════════════════════════════════════════════════════════
//  ROOT APP WIDGET
// ════════════════════════════════════════════════════════════
class BillifyApp extends StatelessWidget {
  const BillifyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return GetMaterialApp(
      // ── Identity ──
      title:           'Billify',
      debugShowCheckedModeBanner: false,

      // ── Themes ──
      theme:     BillifyTheme.light,
      darkTheme: BillifyTheme.dark,
      themeMode: ThemeMode.system,

      // ── Default route ──
      initialRoute: AppRoutes.splash,

      // ── All named routes ──
      getPages: [
        // Splash
        GetPage(
          name:       AppRoutes.splash,
          page:       () => const SplashScreen(),
          transition: Transition.fadeIn,
        ),

        // Auth
        GetPage(
          name:       AppRoutes.login,
          page:       () => const LoginScreen(),
          transition: Transition.fadeIn,
        ),
        GetPage(
          name:       AppRoutes.register,
          page:       () => const RegisterScreen(),
          transition: Transition.rightToLeft,
        ),
        GetPage(
          name:       AppRoutes.forgotPassword,
          page:       () => const ForgotPasswordScreen(),
          transition: Transition.rightToLeft,
        ),

        // Onboarding
        GetPage(
          name:       AppRoutes.termsConditions,
          page:       () => const TermsConditionsScreen(),
          transition: Transition.upToDown,
          middlewares: [AuthMiddleware()],
        ),

        // Main App — protected by AuthMiddleware
        GetPage(
          name:       AppRoutes.dashboard,
          page:       () => const DashboardScreen(),
          transition: Transition.fadeIn,
          middlewares: [AuthMiddleware()],
        ),
        GetPage(
          name:       AppRoutes.invoices,
          page:       () => const InvoiceListScreen(),
          transition: Transition.rightToLeft,
          middlewares: [AuthMiddleware()],
        ),
        GetPage(
          name:       AppRoutes.invoiceCreate,
          page:       () => const InvoiceCreateScreen(),
          transition: Transition.rightToLeft,
          middlewares: [AuthMiddleware()],
        ),
        GetPage(
          name:       AppRoutes.invoiceEdit,
          page:       () => const InvoiceEditScreen(),
          transition: Transition.rightToLeft,
          middlewares: [AuthMiddleware()],
        ),
        GetPage(
          name:       AppRoutes.invoiceDetail,
          page:       () => const InvoiceDetailScreen(),
          transition: Transition.rightToLeft,
          middlewares: [AuthMiddleware()],
        ),
        GetPage(
          name:       AppRoutes.expenses,
          page:       () => const ExpenseListScreen(),
          transition: Transition.rightToLeft,
          middlewares: [AuthMiddleware()],
        ),
        GetPage(
          name:       AppRoutes.expenseAdd,
          page:       () => const AddExpenseScreen(),
          transition: Transition.rightToLeft,
          middlewares: [AuthMiddleware()],
        ),
        GetPage(
          name:       AppRoutes.profile,
          page:       () => const ProfileScreen(),
          transition: Transition.rightToLeft,
          middlewares: [AuthMiddleware()],
        ),
        GetPage(
          name:       AppRoutes.settings,
          page:       () => const SettingsScreen(),
          transition: Transition.rightToLeft,
          middlewares: [AuthMiddleware()],
        ),
      ],
    );
  }
}

// ════════════════════════════════════════════════════════════
//  SPLASH SCREEN — routing logic
// ════════════════════════════════════════════════════════════
class SplashScreen extends StatefulWidget {
  const SplashScreen({super.key});

  @override
  State<SplashScreen> createState() => _SplashScreenState();
}

class _SplashScreenState extends State<SplashScreen>
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;
  late Animation<double>   _fadeAnim;
  late Animation<double>   _scaleAnim;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync:    this,
      duration: const Duration(milliseconds: 1200),
    );
    _fadeAnim  = Tween<double>(begin: 0, end: 1).animate(
      CurvedAnimation(parent: _controller, curve: Curves.easeIn),
    );
    _scaleAnim = Tween<double>(begin: 0.7, end: 1).animate(
      CurvedAnimation(parent: _controller, curve: Curves.elasticOut),
    );

    _controller.forward();
    _navigate();
  }

  /// Decides where to send the user after splash
  Future<void> _navigate() async {
    await Future.delayed(const Duration(milliseconds: 2200));

    final user = FirebaseAuth.instance.currentUser;

    if (user == null) {
      // Not logged in → Login
      Get.offAllNamed(AppRoutes.login);
      return;
    }

    // Check if terms have been accepted (Firestore)
    try {
      final doc = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .get();

      final termsAccepted = doc.data()?['termsAccepted'] ?? false;

      if (termsAccepted) {
        Get.offAllNamed(AppRoutes.dashboard);
      } else {
        Get.offAllNamed(AppRoutes.termsConditions);
      }
    } catch (_) {
      // Fallback: send to login on any Firestore error
      Get.offAllNamed(AppRoutes.login);
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: BillifyColors.primary,
      body: Center(
        child: FadeTransition(
          opacity: _fadeAnim,
          child: ScaleTransition(
            scale: _scaleAnim,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                // Logo container
                Container(
                  width:  100,
                  height: 100,
                  decoration: BoxDecoration(
                    color:        Colors.white,
                    borderRadius: BorderRadius.circular(24),
                    boxShadow: [
                      BoxShadow(
                        color:      Colors.black.withOpacity(0.2),
                        blurRadius: 20,
                        offset: const Offset(0, 8),
                      ),
                    ],
                  ),
                  child: const Center(
                    child: Icon(
                      Icons.receipt_long_rounded,
                      color: BillifyColors.primary,
                      size: 56,
                    ),
                  ),
                ),
                const SizedBox(height: 20),
                // App name
                Text(
                  'Billify',
                  style: GoogleFonts.poppins(
                    fontSize:   38,
                    fontWeight: FontWeight.w800,
                    color:      Colors.white,
                    letterSpacing: 1.5,
                  ),
                ),
                const SizedBox(height: 6),
                Text(
                  'Smart Invoicing. Simple Finance.',
                  style: GoogleFonts.nunito(
                    fontSize: 14,
                    color:    Colors.white70,
                    letterSpacing: 0.5,
                  ),
                ),
                const SizedBox(height: 40),
                // Loading indicator
                SizedBox(
                  width:  40,
                  height: 40,
                  child: CircularProgressIndicator(
                    valueColor: AlwaysStoppedAnimation<Color>(
                      BillifyColors.accent,
                    ),
                    strokeWidth: 3,
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

// ════════════════════════════════════════════════════════════
//  SIDE DRAWER — shared across all main screens
// ════════════════════════════════════════════════════════════
class BillifyDrawer extends StatelessWidget {
  final String activeRoute;
  const BillifyDrawer({super.key, required this.activeRoute});

  void _logout() {
    Get.dialog(
      AlertDialog(
        title: const Text('Logout'),
        content: const Text('Are you sure you want to logout from Billify?'),
        actions: [
          TextButton(
            onPressed: () => Get.back(),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            style: ElevatedButton.styleFrom(
              backgroundColor: BillifyColors.unpaid,
            ),
            onPressed: () async {
              await FirebaseAuth.instance.signOut();
              Get.offAllNamed(AppRoutes.login);
            },
            child: const Text('Logout'),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final user = FirebaseAuth.instance.currentUser;

    return Drawer(
      child: Column(
        children: [
          // ── Drawer Header ──
          UserAccountsDrawerHeader(
            decoration: const BoxDecoration(
              color: BillifyColors.primary,
            ),
            currentAccountPicture: CircleAvatar(
              backgroundColor: Colors.white,
              backgroundImage: user?.photoURL != null
                  ? NetworkImage(user!.photoURL!)
                  : null,
              child: user?.photoURL == null
                  ? const Icon(Icons.person, color: BillifyColors.primary, size: 36)
                  : null,
            ),
            accountName: Text(
              user?.displayName ?? 'Billify User',
              style: GoogleFonts.poppins(
                fontWeight: FontWeight.w600,
                fontSize:   15,
              ),
            ),
            accountEmail: Text(
              user?.email ?? '',
              style: GoogleFonts.nunito(fontSize: 13),
            ),
          ),

          // ── Nav Items ──
          Expanded(
            child: ListView(
              padding: EdgeInsets.zero,
              children: [
                _NavItem(
                  icon:        Icons.dashboard_rounded,
                  label:       'Dashboard',
                  route:       AppRoutes.dashboard,
                  activeRoute: activeRoute,
                ),
                _NavItem(
                  icon:        Icons.receipt_long_rounded,
                  label:       'Invoices',
                  route:       AppRoutes.invoices,
                  activeRoute: activeRoute,
                ),
                _NavItem(
                  icon:        Icons.account_balance_wallet_rounded,
                  label:       'Expenses & Income',
                  route:       AppRoutes.expenses,
                  activeRoute: activeRoute,
                ),
                _NavItem(
                  icon:        Icons.person_rounded,
