                  route:       AppRoutes.profile,
                  activeRoute: activeRoute,
                ),
                const Divider(height: 1),
                _NavItem(
                  icon:        Icons.description_rounded,
                  label:       'Terms & Conditions',
                  route:       AppRoutes.termsConditions,
                  activeRoute: activeRoute,
                ),
                _NavItem(
                  icon:        Icons.settings_rounded,
